import{s as e}from"./i18n-BSBp_gjh.js";import{t}from"./buildPage-DWQZYYcs.js";var n=t({slug:`skill-roadmap`,heroTitle:e({defaultMessage:`Build your skill roadmap in minutes`,id:`3f7d3d2ba4`}),heroSubtitle:e({defaultMessage:`Perplexity Computer analyzes your current skills, researches market demand, and delivers a personalized learning roadmap with resources and milestones — automatically.`,id:`f00ada6575`}),inputUrlCta:e({defaultMessage:`Build my roadmap`,id:`a970bf7f5b`}),inputUrlPlaceholder:`e.g. your LinkedIn or portfolio URL`,inputUrlPrefill:e({defaultMessage:`Go to {url} and research this person's professional background to build a personalized skill roadmap. (1) Analyze their profile for current skills, experience level, industry, content focus, and career trajectory. (2) Research high-demand skills in their field — what top creators, freelancers, and professionals in this space are learning, what clients and employers are paying premium rates for, and what skills are emerging. (3) Identify the top 5 skill gaps between their current profile and the most valuable opportunities in their space — prioritized by income potential and market demand. (4) Build a 90-day learning roadmap for each priority skill — with specific courses, tutorials, projects, and milestones to demonstrate competency. (5) Deliver the complete skill roadmap with a skills assessment, gap analysis, learning resources ranked by quality, portfolio project ideas to showcase each new skill, and a weekly study schedule — organized by priority and estimated time investment.`,id:`4575175b5b`}),heroOverlaySteps:[e({defaultMessage:`Analyzing your skills, experience, and professional background`,id:`6353fdfadf`}),e({defaultMessage:`Researching high-demand skills and market opportunities in your field`,id:`29866613d9`}),e({defaultMessage:`Building 90-day learning roadmap with courses, projects, and milestones`,id:`5cf46d27f9`}),e({defaultMessage:`Complete skill roadmap with resources, portfolio projects, and weekly schedule — ready to start`,id:`c73965aef5`})],generatingSteps:[e({defaultMessage:`Visiting {url} to analyze your current skills, experience, and career trajectory`,id:`d528b97377`}),e({defaultMessage:`Designing an agent to research high-demand skills and market opportunities in your field`,id:`c93327db44`}),e({defaultMessage:`Configuring learning roadmap with courses, projects, and competency milestones`,id:`c8a0f813b1`}),e({defaultMessage:`Setting up the complete skill roadmap with weekly schedule and portfolio project ideas`,id:`a1a368adbe`})],featureSectionTitle:e({defaultMessage:`From skill gaps to market-ready expertise`,id:`d489700be2`}),featureCardTitles:[e({defaultMessage:`Connects to your creator stack`,id:`a825dc5720`}),e({defaultMessage:`A roadmap you can follow today`,id:`648251f455`})],featureCardDescriptions:[e({defaultMessage:`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,id:`830a0b38e3`}),e({defaultMessage:`Notion, Google Docs, Google Sheets, Slack — Computer delivers your learning roadmap, resource lists, and weekly schedule into the tools you already use.`,id:`df620be189`}),e({defaultMessage:`Skills assessment. Gap analysis. Curated courses. Portfolio projects. Weekly study schedule. Computer delivers a personalized learning plan you can start immediately.`,id:`a8973c5b3a`})],capabilitySectionTitle:e({defaultMessage:`Your career coach, on autopilot`,id:`1955016d05`}),capabilitySectionSubtitle:e({defaultMessage:`Enter your profile, get back a personalized skill roadmap with learning resources.`,id:`524e1d3916`}),capabilityCards:[{title:e({defaultMessage:`Skills & Market Research`,id:`ceb06fd45c`}),description:e({defaultMessage:`Computer can analyze your current skills against market demand — and identify the highest-value skill gaps where learning investment will yield the greatest return.`,id:`a4cb4991e2`})},{title:e({defaultMessage:`Gap Analysis & Prioritization`,id:`22fc0da53c`}),description:e({defaultMessage:`Computer can rank skill gaps by income potential, market demand, and learning difficulty — so you focus on the skills that move the needle fastest.`,id:`1e9eda2ceb`})},{title:e({defaultMessage:`90-Day Learning Roadmap`,id:`909440cac4`}),description:e({defaultMessage:`Computer can build a week-by-week learning plan with specific courses, tutorials, practice projects, and milestones — tailored to your available time and learning style.`,id:`4931ce7e61`})},{title:e({defaultMessage:`Connect Your Tools`,id:`723b1a4d3a`}),description:e({defaultMessage:`Computer can push your roadmap to Notion, Google Docs, Google Sheets, and Slack — build learning workflows and track progress across your tools.`,id:`46c3db20c2`})},{title:e({defaultMessage:`Knows Your Goals`,id:`3d8fdcb14b`}),description:e({defaultMessage:`Computer can remember your skills, learning progress, career goals, and completed milestones across sessions — so every roadmap update reflects where you are now.`,id:`b27513ec17`})},{title:e({defaultMessage:`Market Trend Alerts`,id:`fb84f29f8b`}),description:e({defaultMessage:`Computer can monitor skill demand trends in your field monthly — and alert you when a new skill emerges or an existing skill becomes more valuable in the market.`,id:`1edfe7eab6`})}]});export{n as default};
